      { q: "रामस्वरूप ने उमा को बी.ए. पास होने के बाद भी क्या बताया?", options: ["वह डॉक्टर है","केवल कम पढ़ी-लिखी है, यह जताने की कोशिश की","वह नौकरी करती है","वह एम.ए. है"], answer: 1, explain: "वे जान-बूझकर उसकी पढ़ाई छिपाने का प्रयास करते हैं क्योंकि गोपालप्रसाद अधिक पढ़ी-लिखी बहू नहीं चाहते।", level: 2 },
      { q: "उमा के चश्मे को देखकर गोपालप्रसाद ने क्या अनुमान लगाया?", options: ["कि वह बहुत पढ़ती है","कि वह धनी है","कि वह बीमार है","कि वह अभिमानी है"], answer: 0, explain: "उन्होंने पूछा कि चश्मा पढ़ाई की वजह से तो नहीं; रामस्वरूप ने आँख दुखने की बात बना दी।", level: 2 },
      { q: "उमा ने कुर्सी-मेज़ बिकने की बात क्यों कही?", options: ["घर के सामान की चर्चा करने के लिए","मेज़ बेचने के लिए","लड़की को वस्तु की तरह परखने की प्रथा पर चोट करने के लिए","सामान की क़ीमत बताने के लिए"], answer: 2, explain: "उमा के अनुसार लड़की को खरीदार को दिखाई जाने वाली वस्तु की तरह रखा गया है, जो अपमानजनक है।", level: 2 },
      { q: "शंकर के बारे में उमा का कौन-सा आरोप गोपालप्रसाद को सबसे अधिक आहत करता है?", options: ["कि वह परीक्षा में फ़ेल हो गया","कि वह बेरोज़गार है","कि वह लड़कियों के हॉस्टल के चक्कर काटता था और भगाया गया था","कि उसे संगीत नहीं आता"], answer: 2, explain: "यह बात उसके चरित्र की कमज़ोरी और कायरता उजागर करती है।", level: 2 },
      { q: "शीर्षक में 'रीढ़ की हड्डी' किसका प्रतीक है?", options: ["शारीरिक शक्ति का","बीमारी का","लंबाई का","आत्मसम्मान और नैतिक साहस का"], answer: 3, explain: "रीढ़ की हड्डी यहाँ चरित्र की दृढ़ता और आत्मसम्मान का प्रतीक है।", level: 3 },
      { q: "गोपालप्रसाद की दोहरी मानसिकता यहाँ कैसे दिखती है?", options: ["वे बेटे के लिए बहू नहीं चाहते","वे ख़ुद पढ़े-लिखे हैं पर बहू को कम पढ़ी-लिखी चाहते हैं","वे दहेज के विरोधी हैं","वे कम पढ़े-लिखे हैं"], answer: 1, explain: "वे वकील होकर भी स्त्री-शिक्षा के विरोधी हैं – यही उनकी दकियानूसी और दोहरी सोच है।", level: 3 },
      { q: "'मोर के पंख होते हैं, मोरनी के नहीं' जैसे कथन का क्या प्रभाव एकांकी में दिखता है?", options: ["वे स्त्रियों के प्रति उनकी भेदभावपूर्ण और रूढ़िवादी सोच को उजागर करते हैं","वे पक्षियों की जानकारी देते हैं","वे बच्चों को बहलाते हैं","वे हास्य के लिए हैं"], answer: 0, explain: "ऐसे तर्कों से गोपालप्रसाद स्त्रियों को पुरुषों से कमतर सिद्ध करने की कोशिश करते हैं।", level: 3 }
