      { q: "कविता में बार-बार दोहराई जाने वाली पंक्ति किसके मुँह से कहानी सुनने की बात कहती है?", options: ["बुंदेले हरबोलों के","वृद्ध सैनिकों के","रानी के सेवकों के","अंग्रेज़ों के"], answer: 0, explain: "हर छंद का अंत इसी टेक से होता है।", level: 2 },
      { q: "रानी लक्ष्मीबाई को बचपन में क्या कहा जाता था?", options: ["मनु","दुर्गा","छबीली","रानी बेटी"], answer: 2, explain: "कविता में उन्हें नाना की मुँहबोली बहन 'छबीली' कहा गया है।", level: 2 },
      { q: "डलहौजी को झाँसी हड़पने का अवसर क्यों मिला?", options: ["रानी ने उसे आमंत्रित किया","रानी के पति की मृत्यु हो चुकी थी और संतान नहीं थी","झाँसी की सेना कमज़ोर थी","रानी देश छोड़ गई थीं"], answer: 1, explain: "निःसंतान राजा की मृत्यु पर अंग्रेज़ों ने विलय की नीति से राज्य हड़पना चाहा।", level: 2 },
      { q: "रानी के बचपन में कौन-से हथियार उनकी सहेलियाँ थे?", options: ["धनुष-बाण","बंदूक और तोप","कलम और दवात","बरछी, ढाल, कृपाण और कटारी"], answer: 3, explain: "कविता में बरछी, ढाल, कृपाण और कटारी को उनकी सहेली बताया गया है।", level: 2 },
      { q: "रानी लक्ष्मीबाई के संघर्ष में किस भाव की प्रधानता है?", options: ["लोभ","ईर्ष्या","भय","देशप्रेम और वीरता"], answer: 3, explain: "कविता वीर रस प्रधान है और रानी की बहादुरी से भरी है।", level: 2 },
      { q: "'अश्रुपूर्ण रानी ने देखा झाँसी हुई बिरानी थी' पंक्ति में कौन-सा भाव है?", options: ["झाँसी के पराया हो जाने की पीड़ा","आनंद","उत्साह","क्रोध का अभाव"], answer: 0, explain: "झाँसी को अंग्रेज़ों के हाथ जाते देखकर रानी का हृदय दुःख से भर गया।", level: 3 },
      { q: "अंग्रेज़ों की विलय की नीति से कविता में किन रियासतों का उल्लेख हुआ है?", options: ["केवल झाँसी","केवल दिल्ली","सतारा, नागपुर, उदयपुर, तंजौर आदि","केवल बंगाल"], answer: 2, explain: "कविता में कई रियासतों और शहरों का उल्लेख है जिनके साथ अन्याय हुआ।", level: 3 },
      { q: "रानी की अंतिम लड़ाई का कविता में किस रूप में चित्रण है?", options: ["आत्मसमर्पण का","घायल होकर भी साहस के साथ वीरगति को प्राप्त होने का","पलायन का","संधि का"], answer: 1, explain: "कविता कहती है कि घायल होकर भी वे सिंहनी की तरह वीरगति को प्राप्त हुईं।", level: 3 }
